const getTextStoryIndex = block => {
    const match = /^text_story_(\d{1,3})$/.exec(String(block || ""));
    if (!match) return 0;
    const index = Number(match[1]);
    return Number.isInteger(index) && index >= 1 && index <= TEXT_STORY_BLOCK_MAX ? index : 0;
};
